window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fa8c126faa14b0ab"]={"versions": [{"id": "FIG-fa8c126faa14b0ab", "releases": ["R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Informationsfluss- und Komponentendiagramm (<code>class HM_InternalFlow</code>) zur Darstellung von Daten- und Kontrollflüssen («flow») zwischen Funktionsblöcken und Systementitäten.</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Das Diagramm spezifiziert die funktionale Binnenarchitektur des AUTOSAR Health Monitoring (Foundation-Konzept, adaptiert in Classic Platform via <code>WdgM</code> und Adaptive Platform via <code>PHM</code>). Es bildet die dreistufige Verarbeitungskette (Supervision $\\rightarrow$ Statusbestimmung $\\rightarrow$ Reaktionsbestimmung) eines Überwachungszyklus ab und definiert die zustandsbehaftete Datenübergabe zwischen aufeinanderfolgenden Auswertungszyklen (<code>previous instance</code> $\\rightarrow$ <code>next instance</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Instanzen (Komponenten-Klassifikatoren)</p>\n<ul class=\"fig-list\">\n<li><strong><code>:Health Monitoring</code> (Zentrale Systemkomponente):</strong> Kapselt die dreiteilige Überwachungspipeline:</li>\n<li><strong><code>:Execution of Supervision Functions</code>:</strong> Berechnet elementare Überwachungsergebnisse auf Basis gemeldeter Checkpoints.</li>\n<li><strong><code>:Determination of Supervision Status</code>:</strong> Aggregiert Einzelergebnisse zu lokalen und globalen Überwachungszuständen.</li>\n<li><strong><code>:Determination of Actions</code>:</strong> Leitet deterministische Aktionen aus dem Gesamtzustand und externen Statusmeldungen ab.</li>\n<li><strong><code>:Supervised Entity</code>:</strong> Überwachte Software-Einheit (SW-C-Runnable, OS-Task, Adaptive Process/Thread).</li>\n<li><strong><code>:Health Channel</code>:</strong> Asynchroner Statuskanal für externe Zustandsindikatoren (z. B. Hardware-Fehlerbits, Stack-Overflows, BIST-Meldungen).</li>\n<li><strong><code>:Watchdog</code>:</strong> Zielinstanz für Refresh-/Trigger-Kommandos (z. B. WdgIf/WdgM in CP bzw. Daemon/Hardware-Watchdog in AP).</li>\n<li><strong><code>:External error handlers</code>:</strong> Eskalationsziele für erkannte Fehlerzustände (z. B. Dem, Det, Platform Health Management Error Hooks, Recovery-Actions).</li>\n<li><strong><code>previous instance</code> / <code>next instance: Health Monitoring</code>:</strong> Modellierung des zustandsbehafteten Zyklus-zu-Zyklus-Speichers (persistenter Monitoring-Kontext).</li>\n</ul>\n<p class=\"fig-p\">#### Datenstrukturen & Informationsflüsse («flow»)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Checkpoint</code> («flow»):</strong> Laufzeitereignisse (Checkpoint-IDs, Timestamps/Ticks) von <code>:Supervised Entity</code> an <code>:Execution of Supervision Functions</code>.</li>\n<li><strong><code>Health Status</code> («flow»):</strong> Qualitative System- und Hardwarezustandsvektoren von <code>:Health Channel</code> direkt in <code>:Determination of Actions</code>.</li>\n<li><strong><code>Supervision Res</code> («flow»):</strong> Binäre/Teilergebnisse (<code>correct</code> / <code>incorrect</code>) der drei Kernüberwachungen (Alive-, Deadline-, Logical Supervision).</li>\n<li><strong><code>Supervision Results, Local Supervision Statuses, Global Supervision Status</code> («flow»):</strong> Vollständiger Statusvektor zur Aktionsbestimmung.</li>\n<li><strong><code>Watchdog Commands</code> («flow»):</strong> Triggerimpulse, Window-Watchdog-Zähler oder Trigger-Unterdrückung bei Fehlern.</li>\n<li><strong><code>Error handler IDs to be invoked</code> («flow»):</strong> Explizite Fehlerreaktions- und Callback-Identifikatoren zur deterministischen Fehlerbehandlung.</li>\n<li><strong>Zyklus-Persistenz-Vektor («flow»):</strong> Enthält <code>Checkpoints</code>, <code>Health Statuses</code>, <code>Supervision Results</code>, <code>Local Supervision Status</code>, <code>Global Supervision Status</code>, <code>Watchdog Commands</code> und <code>Error Handler IDs</code> zur Historienfortschreibung in den Folgezyklus.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Zyklus-Initialisierung & Kontextübernahme:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Übernahme des kumulierten Überwachungszustands und der Zähler/Fensterhistorie aus der vorhergehenden Auswertung (<code>previous instance</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stufe 1: Ausführung der Supervision-Funktionen (<code>Execution of Supervision Functions</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verarbeitung eingetroffener Checkpoints aus den <code>Supervised Entities</code>.</li>\n<li>Parallele/sequentielle Auswertung von:</li>\n<li><em>Alive Supervision:</em> Zählen der Checkpoints innerhalb des definierten Überwachungsintervalls (Toleranzfenster min/max).</li>\n<li><em>Deadline Supervision:</em> Zeitdifferenzmessung zwischen Transitionen zweier Checkpoints.</li>\n<li><em>Logical Supervision:</em> Verifikation des Kontrollflusses anhand statischer Graph-Topologien (Transition Validierung).</li>\n<li>Ausgabe: Elementare Testergebnisse (<code>Supervision Res</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stufe 2: Statuskonsolidierung (<code>Determination of Supervision Status</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aggregation der Einzelprüfungen zum <code>Local Supervision Status</code> pro Supervised Entity (z. B. <code>CORRECT</code>, <code>FAILED</code>, <code>EXPIRED</code>).</li>\n<li>Überführung der lokalen Zustände in den <code>Global Supervision Status</code> der Platform/Partition (Zustandsautomat inkl. Fehlertoleranzzähler).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stufe 3: Reaktionsphase (<code>Determination of Actions</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Korrelation aus <code>Global Supervision Status</code>, <code>Local Supervision Statuses</code> und asynchron gemeldeten Werten aus <code>:Health Channel</code>.</li>\n<li>Bei Status <code>CORRECT</code>/<code>OK</code>: Generierung der regulären <code>Watchdog Commands</code> (Trigger-Auffrischung).</li>\n<li>Bei Fehlern/Status <code>EXPIRED</code>:</li>\n<li>Unterdrückung des Watchdog-Triggers (führt zu HW-Reset via Watchdog).</li>\n<li>Selektion und Auslösung spezifischer Handler (<code>Error handler IDs to be invoked</code>) via synchronen/asynchronen Callback (z. B. Dem Event Reporting, Safe State Transition, Process Restart).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklus-Abschluss:</strong> Serialisierung des aktuellen Gesamtzustandsvektors für <code>next instance</code>.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Applikations- & SW-C-Entwickler:</strong></li>\n<li>Checkpoint-Instrumentierung (<code>ReportCheckpoint()</code>) muss jitterarm und streng deterministisch erfolgen; unzulässige Graph-Übergänge triggern unmittelbar die <em>Logical Supervision</em>.</li>\n<li>Ausführungszyklen der Runnables müssen exakt mit den konfigurierten Alive- und Deadline-Parametern harmonisiert werden.</li>\n<li><strong>Stack- & Integrations-Entwickler:</strong></li>\n<li><strong>Zyklustreue:</strong> Die Ausführung von <code>Health Monitoring</code> muss in einer hochprioritären, deterministischen zyklischen Task/Thread erfolgen, um Watchdog-Timeouts zu verhindern.</li>\n<li><strong>Zustandskonsistenz (<code>previous</code>/<code>next instance</code>):</strong> In Multi-Core- oder partitionierten Architekturen (Memory Protection, ASIL-D-Dekompensierung) muss der Zyklus-Persistenz-Vektor atomar bzw. sperrfrei über Doppelpuffer/Lockless Queues ausgetauscht werden.</li>\n<li><strong>Aktionsentkopplung:</strong> Externe Error-Handler (<code>Error handler IDs</code>) dürfen die zentrale Überwachungsschleife niemals blockieren; langwierige Recovery-Prozeduren müssen asynchron ausgelagert werden.</li>\n</ul>"}, {"id": "FIG-3fd7acc3b2466443", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Informationsfluss- und Komponentendiagramm (<code>class HM_InternalFlow</code>) zur Darstellung von Daten- und Kontrollflüssen («flow») zwischen Funktionsblöcken und Systementitäten.</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Das Diagramm spezifiziert die funktionale Binnenarchitektur des AUTOSAR Health Monitoring (Foundation-Konzept, adaptiert in Classic Platform via <code>WdgM</code> und Adaptive Platform via <code>PHM</code>). Es bildet die dreistufige Verarbeitungskette (Supervision $\\rightarrow$ Statusbestimmung $\\rightarrow$ Reaktionsbestimmung) eines Überwachungszyklus ab und definiert die zustandsbehaftete Datenübergabe zwischen aufeinanderfolgenden Auswertungszyklen (<code>previous instance</code> $\\rightarrow$ <code>next instance</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure & Instanzen (Komponenten-Klassifikatoren)</p>\n<ul class=\"fig-list\">\n<li><strong><code>:Health Monitoring</code> (Zentrale Systemkomponente):</strong> Kapselt die dreiteilige Überwachungspipeline:</li>\n<li><strong><code>:Execution of Supervision Functions</code>:</strong> Berechnet elementare Überwachungsergebnisse auf Basis gemeldeter Checkpoints.</li>\n<li><strong><code>:Determination of Supervision Status</code>:</strong> Aggregiert Einzelergebnisse zu lokalen und globalen Überwachungszuständen.</li>\n<li><strong><code>:Determination of Actions</code>:</strong> Leitet deterministische Aktionen aus dem Gesamtzustand und externen Statusmeldungen ab.</li>\n<li><strong><code>:Supervised Entity</code>:</strong> Überwachte Software-Einheit (SW-C-Runnable, OS-Task, Adaptive Process/Thread).</li>\n<li><strong><code>:Health Channel</code>:</strong> Asynchroner Statuskanal für externe Zustandsindikatoren (z. B. Hardware-Fehlerbits, Stack-Overflows, BIST-Meldungen).</li>\n<li><strong><code>:Watchdog</code>:</strong> Zielinstanz für Refresh-/Trigger-Kommandos (z. B. WdgIf/WdgM in CP bzw. Daemon/Hardware-Watchdog in AP).</li>\n<li><strong><code>:External error handlers</code>:</strong> Eskalationsziele für erkannte Fehlerzustände (z. B. Dem, Det, Platform Health Management Error Hooks, Recovery-Actions).</li>\n<li><strong><code>previous instance</code> / <code>next instance: Health Monitoring</code>:</strong> Modellierung des zustandsbehafteten Zyklus-zu-Zyklus-Speichers (persistenter Monitoring-Kontext).</li>\n</ul>\n<p class=\"fig-p\">#### Datenstrukturen & Informationsflüsse («flow»)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Checkpoint</code> («flow»):</strong> Laufzeitereignisse (Checkpoint-IDs, Timestamps/Ticks) von <code>:Supervised Entity</code> an <code>:Execution of Supervision Functions</code>.</li>\n<li><strong><code>Health Status</code> («flow»):</strong> Qualitative System- und Hardwarezustandsvektoren von <code>:Health Channel</code> direkt in <code>:Determination of Actions</code>.</li>\n<li><strong><code>Supervision Res</code> («flow»):</strong> Binäre/Teilergebnisse (<code>correct</code> / <code>incorrect</code>) der drei Kernüberwachungen (Alive-, Deadline-, Logical Supervision).</li>\n<li><strong><code>Supervision Results, Local Supervision Statuses, Global Supervision Status</code> («flow»):</strong> Vollständiger Statusvektor zur Aktionsbestimmung.</li>\n<li><strong><code>Watchdog Commands</code> («flow»):</strong> Triggerimpulse, Window-Watchdog-Zähler oder Trigger-Unterdrückung bei Fehlern.</li>\n<li><strong><code>Error handler IDs to be invoked</code> («flow»):</strong> Explizite Fehlerreaktions- und Callback-Identifikatoren zur deterministischen Fehlerbehandlung.</li>\n<li><strong>Zyklus-Persistenz-Vektor («flow»):</strong> Enthält <code>Checkpoints</code>, <code>Health Statuses</code>, <code>Supervision Results</code>, <code>Local Supervision Status</code>, <code>Global Supervision Status</code>, <code>Watchdog Commands</code> und <code>Error Handler IDs</code> zur Historienfortschreibung in den Folgezyklus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Zyklus-Initialisierung & Kontextübernahme:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Übernahme des kumulierten Überwachungszustands und der Zähler/Fensterhistorie aus der vorhergehenden Auswertung (<code>previous instance</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stufe 1: Ausführung der Supervision-Funktionen (<code>Execution of Supervision Functions</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Verarbeitung eingetroffener Checkpoints aus den <code>Supervised Entities</code>.</li>\n<li>Parallele/sequentielle Auswertung von:</li>\n<li><em>Alive Supervision:</em> Zählen der Checkpoints innerhalb des definierten Überwachungsintervalls (Toleranzfenster min/max).</li>\n<li><em>Deadline Supervision:</em> Zeitdifferenzmessung zwischen Transitionen zweier Checkpoints.</li>\n<li><em>Logical Supervision:</em> Verifikation des Kontrollflusses anhand statischer Graph-Topologien (Transition Validierung).</li>\n<li>Ausgabe: Elementare Testergebnisse (<code>Supervision Res</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stufe 2: Statuskonsolidierung (<code>Determination of Supervision Status</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aggregation der Einzelprüfungen zum <code>Local Supervision Status</code> pro Supervised Entity (z. B. <code>CORRECT</code>, <code>FAILED</code>, <code>EXPIRED</code>).</li>\n<li>Überführung der lokalen Zustände in den <code>Global Supervision Status</code> der Platform/Partition (Zustandsautomat inkl. Fehlertoleranzzähler).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stufe 3: Reaktionsphase (<code>Determination of Actions</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Korrelation aus <code>Global Supervision Status</code>, <code>Local Supervision Statuses</code> und asynchron gemeldeten Werten aus <code>:Health Channel</code>.</li>\n<li>Bei Status <code>CORRECT</code>/<code>OK</code>: Generierung der regulären <code>Watchdog Commands</code> (Trigger-Auffrischung).</li>\n<li>Bei Fehlern/Status <code>EXPIRED</code>:</li>\n<li>Unterdrückung des Watchdog-Triggers (führt zu HW-Reset via Watchdog).</li>\n<li>Selektion und Auslösung spezifischer Handler (<code>Error handler IDs to be invoked</code>) via synchronen/asynchronen Callback (z. B. Dem Event Reporting, Safe State Transition, Process Restart).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zyklus-Abschluss:</strong> Serialisierung des aktuellen Gesamtzustandsvektors für <code>next instance</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Applikations- & SW-C-Entwickler:</strong></li>\n<li>Checkpoint-Instrumentierung (<code>ReportCheckpoint()</code>) muss jitterarm und streng deterministisch erfolgen; unzulässige Graph-Übergänge triggern unmittelbar die <em>Logical Supervision</em>.</li>\n<li>Ausführungszyklen der Runnables müssen exakt mit den konfigurierten Alive- und Deadline-Parametern harmonisiert werden.</li>\n<li><strong>Stack- & Integrations-Entwickler:</strong></li>\n<li><strong>Zyklustreue:</strong> Die Ausführung von <code>Health Monitoring</code> muss in einer hochprioritären, deterministischen zyklischen Task/Thread erfolgen, um Watchdog-Timeouts zu verhindern.</li>\n<li><strong>Zustandskonsistenz (<code>previous</code>/<code>next instance</code>):</strong> In Multi-Core- oder partitionierten Architekturen (Memory Protection, ASIL-D-Dekompensierung) muss der Zyklus-Persistenz-Vektor atomar bzw. sperrfrei über Doppelpuffer/Lockless Queues ausgetauscht werden.</li>\n<li><strong>Aktionsentkopplung:</strong> Externe Error-Handler (<code>Error handler IDs</code>) dürfen die zentrale Überwachungsschleife niemals blockieren; langwierige Recovery-Prozeduren müssen asynchron ausgelagert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-fa8c126faa14b0ab", "to": "FIG-3fd7acc3b2466443", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3fd7acc3b2466443", "to": "FIG-fa8c126faa14b0ab", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
